lement)	if(isMechaniker(hitElement)) then		outputChatBox("[INFO]: Nutze /mechanik um in Dienst zu gehen/den Dienst zu verlassen!", hitElement, 200, 200, 0)	else		outputChatBox("Nur für Mechaniker!", hitElement, 175, 0, 0)	endend)addCommandHandler("mechanik", function(thePlayer)	if(isMechaniker(thePlayer)) and (isElementWithinMarker(thePlayer, duty_marker)) then		local duty = getElementData(thePlayer, "mechaniker:duty")		if(duty == true) then			setElementData(thePlayer, "mechaniker:duty", false)			outputChatBox("[INFO]: Du bist nun nicht mehr als Mechaniker im Dienst!", thePlayer, 200, 200, 0)			takeWeapon(thePlayer, 41)			setElementModel ( thePlayer, laGetElementData ( thePlayer, "skinid" ) )		else			setElementData(thePlayer, "mechaniker:duty", true)			outputChatBox("[INFO]: Du bist nun als Mechaniker im Dienst!", thePlayer, 200, 200, 0)			outputChatBox("[INFO]: Ausserdem hast du 5 Reparaturkits erhalten, /repaircar!", thePlayer, 200, 200, 0)			setElementModel ( thePlayer, 50 )			giveWeapon(thePlayer, 41, 1000, true)			laSetElementData(thePlayer, "repairkits", 5)		end	else		outputChatBox("Du bist kein Mitarbeiter/Nicht nahe genug am Marker!", thePlayer, 150, 0, 0)	endend)local mechanik_blip = {}function WantMech_func ( player )local pname = getPlayerName(player)local x, y, z = getElementPosition ( player )local location = getZoneName ( x, y, z )	if laGetElementData (player, "needMech") == false then		mechanik_blip[player] = createBlip (x, y, z, 0, 2, 0, 0, 255, getRootElement() )		setElementVisibleTo ( mechanik_blip[player], getRootElement(), false )        for index, thePlayer in pairs(getElementsByType("player")) do                if(isMechaniker(thePlayer)) and (isMechanikerDuty(thePlayer)) then					setElementVisibleTo ( mechanik_blip[player], thePlayer, true )                        outputChatBox("Der Spieler "..pname.." benötigt einen Mechaniker in "..location.." ", thePlayer, 200, 200, 0)						setTimer ( delete_mech_blip, 60000, 1, player, thePlayer)						laSetElementData (player, "needMech", true)						outputChatBox ( "Du hast einen Mechaniker angefordert!", player, 0, 150, 0 )                end        end	else		outputChatBox ( "Du hast bereits einen Mechaniker gerufen. Warte 30 Sekunden.", player, 150, 0, 0 )	endendaddCommandHandler("mechaniker", WantMech_func)function delete_mech_blip (player, thePlayer)setElementVisibleTo ( mechanik_blip[player], thePlayer, false )laSetElementData (player, "needMech", false)endlocal marker = {}marker[1] = createMarker(-2687.9560546875, 449.61956787109, 4.3559375, "corona", 1.5, 255, 0, 0, 150) -- Garage draussen-- Davor: -2689.8493652344, 449.50695800781, 4.3359375marker[2] = createMarker(-2685.9626464844, 449.09289550781, 4.3559375, "corona", 1.5, 255, 0, 0, 150) -- Garage drinnen-- Davor: -2684.2702636719, 449.08560180664, 4.3359375addEventHandler("onMarkerHit", marker[1], function(hitElement, dim)if getElementType(hitElement) == "player" and (dim) then	if isPedInVehicle ( hitElement ) == false then		if isMechaniker(hitElement) then			setElementPosition(hitElement, -2684.2702636719, 449.08560180664, 4.3359375)			infobox ( hitElement, "\n\nWillkommen Mechaniker!", 5000, 0, 125, 0 )		else			outputChatBox("Nur für Mechaniker!", hitElement, 175, 0, 0)		end	endendend)	addEventHandler("onMarkerHit", marker[2], function(hitElement, dim)if getElementType(hitElement) == "player" and (dim) then	if isPedInVehicle ( hitElement ) == false then		-- isMechaniker(hitElement) then			setElementPosition(hitElement, -2689.8493652344, 449.50695800781, 4.3359375)		--else		--	outputChatBox("Nur für Mechaniker!", hitElement, 175, 0, 0)		--end	endendend)	function isMechanikerDuty(thePlayer)	if(getElementData(thePlayer, "mechaniker:duty") == true) then		return true;	else		return false;	endendaddCommandHandler("repaircar", function(thePlayer, cmd)		if(isMechaniker(thePlayer)) and (isMechanikerDuty(thePlayer)) then			local vehicle = getPedOccupiedVehicle(thePlayer)			local kits = tonumber(laGetElementData(thePlayer, "repairkits"))			if not(kits) or (kits < 1) then				outputChatBox("Du hast keine Repairkits bei dir! Lade in der Garage in SF welche auf.", thePlayer, 150, 0, 0)				return			end			if vehicle then				local vx, vy, vz = getElementVelocity ( getPedOccupiedVehicle ( player ) )				local speed = math.sqrt ( vx ^ 2 + vy ^ 2 + vz ^ 2 )				local kmh = speed * 180				if kmh < 20 then					setElementFrozen(vehicle, true)					setTimer(function()						setElementFrozen(vehicle, false)						laSetElementData(thePlayer, "repairkits", kits-1)						fixVehicle(vehicle)						if getVehicleOccupant(vehicle) ~= thePlayer then							local target = getVehicleOccupant(vehicle)							outputChatBox("[INFO]: Mechaniker "..getPlayerName(thePlayer).." hat dein Fahrzeug repariert!", target, 0, 150, 0)							outputChatBox("[INFO]: Du hast das Fahrzeug von "..getPlayerName(target).." repariert! Verbleibene Kits: "..(kits-1), thePlayer, 0, 150, 0)						else							outputChatBox("[INFO]: Du hast das Fahrzeug repariert! Verbleibene Kits: "..(kits-1), thePlayer, 0, 150, 0)						end					end, 5000, 1)				else					outputChatBox("Das Fahrzeug steht nicht still!", thePlayer, 150, 0, 0)				end			else				outputChatBox("Du bist in keinem Fahrzeug!", thePlayer, 150, 0, 0)			end		else			outputChatBox("Du bist kein Mechaniker/Nicht im Dienst!", thePlayer, 150, 0, 0)		endend)